// Parser resiliente: extrai o primeiro JSON válido do output do agent e normaliza.
const raw = ($json.output || '').toString();
let parsed = null;

// Tenta parse direto
try { parsed = JSON.parse(raw); } catch (_) {}

// Tenta extrair entre a primeira { e a última }
if (!parsed) {
  const i = raw.indexOf('{');
  const j = raw.lastIndexOf('}');
  if (i >= 0 && j > i) {
    try { parsed = JSON.parse(raw.slice(i, j + 1)); } catch (_) {}
  }
}

if (!parsed || typeof parsed !== 'object') {
  return [{ json: { ok: false, erro: 'IA devolveu formato invalido' } }];
}

const original = (parsed.original || '').toString().trim();
const corrigido = (parsed.corrigido || '').toString().trim();
let sugestoes = Array.isArray(parsed.sugestoes) ? parsed.sugestoes : [];
sugestoes = sugestoes
  .map(s => ({
    titulo: (s && s.titulo ? s.titulo : 'Sugestão').toString().slice(0, 60),
    texto: (s && s.texto ? s.texto : '').toString().trim(),
  }))
  .filter(s => s.texto);

return [{ json: { ok: true, original, corrigido, sugestoes } }];
